put(Path('server/tests/clientIsolationDeliverableTruth.test.ts'), r'''import assert from 'node:assert/strict';import crypto from 'node:crypto';import fs from 'node:fs';import path from 'node:path';import * as XLSXModule from 'xlsx';const XLSX:any=(XLSXModule as any).default||XLSXModule;import {CLIENTS,isolationDir} from './fixtures/clientIsolationFixture.js';import {deliverableFacts,prepareClientIsolation} from './fixtures/clientIsolationAcceptanceHelpers.js';const dir=isolationDir(),reports=path.join(dir,'reports');fs.mkdirSync(reports,{recursive:true});process.env.HERMES_REPORTS_DIR=reports;const {deliverableArtifactService}=await import('../cpaOrganization/deliverableArtifactService.js');const p=await prepareClientIsolation();const out:any={};for(const which of ['ALPHA','BETA'] as const){const c=CLIENTS[which],other=which==='ALPHA'?CLIENTS.BETA:CLIENTS.ALPHA,ownShas=p.sourceShas[which],otherShas=p.sourceShas[which==='ALPHA'?'BETA':'ALPHA'],ownProv=p.provenance[which],otherProv=p.provenance[which==='ALPHA'?'BETA':'ALPHA'];const report=await deliverableArtifactService.compileAndRegisterDeliverable({reportId:`REP-CLIENT-${which}`,engagementId:c.engagementId,workspaceId:c.workspaceId,version:'v1.0',title:`${c.clientName} Evidence Review Draft`,clientName:c.clientName,period:'FY 2026',currency:'USD',status:'AI_PREPARED',facts:deliverableFacts(p.bindings,c.clientId)});assert.ok(report.formats.pdf&&report.formats.json&&report.formats.xlsx&&report.formats.csvLeadSchedules);const pdf=fs.readFileSync(report.formats.pdf!.filepath);assert.equal(crypto.createHash('sha256').update(pdf).digest('hex'),report.formats.pdf!.sha256);const {PDFParse}=await import('pdf-parse');const parser=new PDFParse({data:pdf});let pdfText='';try{pdfText=(await parser.getText()).text;}finally{await parser.destroy();}assert(pdfText.includes(c.clientName));assert(!pdfText.includes(other.clientName));for(const x of ownShas)assert(pdfText.includes(x));for(const x of otherShas)assert(!pdfText.includes(x));for(const x of ownProv)assert(pdfText.includes(x));for(const x of otherProv)assert(!pdfText.includes(x));const jsonText=fs.readFileSync(report.formats.json!.filepath,'utf8'),json=JSON.parse(jsonText);assert.equal(json.workspaceId,c.workspaceId);assert(!jsonText.includes(other.workspaceId));for(const x of otherShas)assert(!jsonText.includes(x));const csv=fs.readFileSync(report.formats.csvLeadSchedules!.filepath,'utf8');for(const x of ownShas)assert(csv.includes(x));for(const x of otherShas)assert(!csv.includes(x));const wb=XLSX.readFile(report.formats.xlsx!.filepath),sheetText=wb.SheetNames.flatMap((n:string)=>(XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,raw:false}) as any[][]).flat()).map(String).join(' | ');for(const x of ownShas)assert(sheetText.includes(x));for(const x of otherShas)assert(!sheetText.includes(x));out[which]={workspaceId:c.workspaceId,formats:{pdf:report.formats.pdf!.sha256,json:report.formats.json!.sha256,xlsx:report.formats.xlsx!.sha256,csv:report.formats.csvLeadSchedules!.sha256}};}fs.writeFileSync(path.join(dir,'deliverable-truth.json'),JSON.stringify({marker:'P2_BULK_CLIENT_ISOLATION_DELIVERABLE_TRUTH=PASS',clients:out},null,2));console.log('P2_BULK_CLIENT_ISOLATION_DELIVERABLE_TRUTH=PASS');
''')

put(Path('src/components/views/engagement/ClientIsolationPanel.tsx'), r'''import React from 'react';const show=(v:any)=>v===null||v===undefined||v===''?'NOT RECORDED':String(v);export const ClientIsolationPanel:React.FC<{review:any}>=({review})=>{if(!review)return null;return <section className="border rounded-xl p-4 space-y-3" data-eve-client-isolation="true"><h2 className="font-semibold">Bulk mixed-client isolation review</h2><p>Status: <strong>{show(review.status)}</strong> · Promotion: <strong>{show(review.promotionState)}</strong></p><p>Action: {show(review.decision)} · Client scopes: {show(review.scopeCount)} · Bindings: {show(review.bindingCount)} · Cross-client leaks: {show(review.crossClientLeakCount)}</p><p>Canonical batch value: <strong>{review.canonicalBatchValue==null?'NOT AGGREGATED':show(review.canonicalBatchValue)}</strong></p><p>Shared filenames, amounts, labels, and periods do not establish client identity. Workspace + engagement + client scope controls every evidence reference.</p><p>Collision stress: filenames={(review.collisionSummary?.sharedFilenames||[]).join(', ')||'NONE'} · values={(review.collisionSummary?.sharedValues||[]).join(', ')||'NONE'} · labels={(review.collisionSummary?.sharedLabels||[]).join(', ')||'NONE'} · periods={(review.collisionSummary?.sharedPeriods||[]).join(', ')||'NONE'}</p><div className="grid gap-3 md:grid-cols-2">{(review.clientSummaries||[]).map((s:any)=><article key={s.clientId} className="border rounded-lg p-3 space-y-1"><h3 className="font-medium">{show(s.clientName)}</h3><p>Client: {show(s.clientId)}</p><p>Workspace: {show(s.workspaceId)}</p><p>Engagement: {show(s.engagementId)}</p><p>Documents: {show(s.documents)} · Provenance: {show(s.provenance)} · Facts: {show(s.facts)}</p><p>Findings: {show(s.findings)} · PBC clarifications: {show(s.clarifications)} · Rendered values: {show(s.renderedValues)}</p></article>)}</div><div className="space-y-2">{(review.bindingResults||[]).map((b:any)=><article key={`${b.kind}-${b.id}`} className="border rounded-lg p-2"><p><strong>{show(b.kind)}</strong> · {show(b.id)} · {show(b.clientName)}</p><p>Workspace: {show(b.workspaceId)} · Engagement: {show(b.engagementId)}{b.value!==undefined?` · Value: USD ${show(b.value)}`:''}</p>{b.sourceSha256&&<p className="break-all">Source SHA-256: {show(b.sourceSha256)}</p>}{b.provenanceId&&<p className="break-all">Provenance: {show(b.provenanceId)}</p>}<p>Issues: {(b.issues||[]).join(' | ')||'NONE'}</p></article>)}</div>{review.issues?.length>0&&<ul className="list-disc pl-5">{review.issues.map((x:string,i:number)=><li key={i}>{x}</li>)}</ul>}</section>;};
''')

put(Path('server/tests/clientIsolationProductTruthBrowser.test.ts'), r'''import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import puppeteer from 'puppeteer-core';import {buildClientEngagement,buildControlEngagement,prepareClientIsolation} from './fixtures/clientIsolationAcceptanceHelpers.js';import {CLIENTS,isolationDir,SHARED_VALUE} from './fixtures/clientIsolationFixture.js';const p=await prepareClientIsolation(),control=await buildControlEngagement(),alpha=await buildClientEngagement('ALPHA'),beta=await buildClientEngagement('BETA');const baseUrl=process.env.EVE_TEST_BASE_URL||'http://127.0.0.1:4173',candidates=[process.env.CHROME_BIN,'/usr/bin/google-chrome','/usr/bin/google-chrome-stable','/usr/bin/chromium','/usr/bin/chromium-browser'].filter(Boolean) as string[],executablePath=candidates.find(x=>fs.existsSync(x));if(!executablePath)throw new Error('MISSING_BROWSER_EXECUTABLE');const browser=await puppeteer.launch({executablePath,headless:true,args:['--no-sandbox','--disable-setuid-sandbox','--disable-dev-shm-usage']});try{const page=await browser.newPage();await page.setViewport({width:1440,height:1400});let mode:'CONTROL'|'ALPHA'|'BETA'='CONTROL';await page.setRequestInterception(true);page.on('request',async req=>{try{const u=new URL(req.url());if(u.origin!==new URL(baseUrl).origin||!u.pathname.startsWith('/api/'))return req.continue();const eng=mode==='CONTROL'?control:mode==='ALPHA'?alpha:beta;let payload:any={};if(u.pathname==='/api/cpa/engagements/universal')payload={engagements:[{engagementId:eng.engagementId,workspaceId:eng.workspaceId,classification:eng.classification,isCustomer:eng.isCustomer,clientName:eng.clientName,period:eng.period,framework:eng.framework,functionalCurrency:'USD',currentStage:'EVIDENCE_REVIEW',openReviewNotesCount:1,documentsCount:eng.documents.length,canonicalFactsCount:eng.facts.length}]};else if(u.pathname===`/api/cpa/engagements/${eng.engagementId}`)payload={engagement:eng};else if(u.pathname==='/api/cpa/reports/library')payload={reports:[]};else if(u.pathname==='/api/queue/jobs')payload={jobs:[]};else if(u.pathname==='/api/health')payload={status:'ok'};await req.respond({status:200,contentType:'application/json',body:JSON.stringify(payload)});}catch{req.abort();}});const load=async(m:'CONTROL'|'ALPHA'|'BETA')=>{mode=m;const r=await page.goto(`${baseUrl}/?view=engagement-evidence&mode=${m}`,{waitUntil:'networkidle0',timeout:30000});assert.ok(r?.ok());await page.waitForSelector('[data-eve-client-isolation="true"]',{visible:true,timeout:15000});return page.$eval('[data-eve-client-isolation="true"]',el=>(el as HTMLElement).innerText);};let text=await load('CONTROL');for(const x of ['Bulk mixed-client isolation review','BLOCKED_CLIENT_IDENTITY_MISMATCH','BLOCKED_CLIENT_ISOLATION','REQUEST_CLIENT_SCOPE_REPAIR','CROSS_CLIENT_FACT_REFERENCE','CROSS_CLIENT_DOCUMENT_REFERENCE','CROSS_CLIENT_PROVENANCE_REFERENCE','NOT AGGREGATED'])assert(text.includes(x),`control missing ${x}`);text=await load('ALPHA');for(const x of ['VERIFIED_CLIENT_ISOLATION',CLIENTS.ALPHA.clientName,CLIENTS.ALPHA.workspaceId,CLIENTS.ALPHA.engagementId,`Value: USD ${SHARED_VALUE}`,...p.sourceShas.ALPHA,...p.provenance.ALPHA])assert(text.includes(String(x)),`alpha missing ${x}`);for(const x of [CLIENTS.BETA.clientName,CLIENTS.BETA.workspaceId,...p.sourceShas.BETA,...p.provenance.BETA])assert(!text.includes(String(x)),`alpha leaked ${x}`);text=await load('BETA');for(const x of ['VERIFIED_CLIENT_ISOLATION',CLIENTS.BETA.clientName,CLIENTS.BETA.workspaceId,CLIENTS.BETA.engagementId,`Value: USD ${SHARED_VALUE}`,...p.sourceShas.BETA,...p.provenance.BETA])assert(text.includes(String(x)),`beta missing ${x}`);for(const x of [CLIENTS.ALPHA.clientName,CLIENTS.ALPHA.workspaceId,...p.sourceShas.ALPHA,...p.provenance.ALPHA])assert(!text.includes(String(x)),`beta leaked ${x}`);const screenshot=path.join(isolationDir(),'client-isolation-product-truth.png');await page.screenshot({path:screenshot,fullPage:true});fs.writeFileSync(path.join(isolationDir(),'product-truth.json'),JSON.stringify({marker:'P2_BULK_CLIENT_ISOLATION_PRODUCT_TRUTH_BROWSER=PASS',controlStatus:p.tamperedReview.status,alphaStatus:p.alphaReview.status,betaStatus:p.betaReview.status,crossClientLeaks:p.tamperedReview.crossClientLeakCount,screenshot:path.basename(screenshot),browserVersion:await browser.version()},null,2));console.log('P2_BULK_CLIENT_ISOLATION_PRODUCT_TRUTH_BROWSER=PASS');}finally{await browser.close();}
''')

